validator:
function validate([n, categories]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is an integer from 1 to 100.';
  if (!Array.isArray(categories) || categories.length !== n) return 'categories needs exactly n labels, one per element.';
  if (categories.some(v => !Number.isSafeInteger(v))) return 'Each category label is an integer.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [n, labels] = input;
  const category = labels.slice();
  // The labels stay inside this closure; the solution can only compare two elements.
  const categoryHandler = Object.freeze({
    haveSameCategory(a, b) {
      if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return false;
      return category[a] === category[b];
    },
  });
  return solve(n, categoryHandler);
}

