function numberOfCategories(n, categoryHandler) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  let categories = n;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const rootI = find(i);
      const rootJ = find(j);
      if (rootI === rootJ) {
        continue;
      }
      if (categoryHandler.haveSameCategory(i, j)) {
        parent[rootJ] = rootI;
        categories--;
      }
    }
  }
  return categories;
}

