function numberOfCategories(n, categoryHandler) {
  // Keep one representative per category seen so far; a new element either matches one of them or starts a new category.
  const representatives = [];
  for (let element = 0; element < n; element++) {
    if (!representatives.some(rep => categoryHandler.haveSameCategory(rep, element))) representatives.push(element);
  }
  return representatives.length;
}

