function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 8);
  const groups = 1 + Math.floor(rand() * n);
  // Labels are spread out so they are not simply 1..groups.
  const labels = Array.from({ length: groups }, () => 1 + Math.floor(rand() * 1000));
  const categories = Array.from({ length: n }, () => labels[Math.floor(rand() * groups)]);
  return [n, categories];
}
